const drawer=document.querySelector('#chatDrawer');const backdrop=document.querySelector('#chatBackdrop');const messages=document.querySelector('#messages');const input=document.querySelector('#chatInput');const preview=document.querySelector('#answerPreview');const toast=document.querySelector('#toast');const launcher=document.querySelector('.assistant-launcher');
const answers={customise:{match:/custom|tailor|requirement|area|size|square|sq ft|1500|4500/i,text:'Yes. Each villa can be tailored around the owner’s preferred space, room arrangement and lifestyle requirements, within an approximate built-up area of 1,500 to 4,500 sq ft.',tag:'TAILORED VILLA',title:'Designed around you',detail:'1,500–4,500 sq ft · flexible planning · personalised requirements',image:'assets/project-02.jpg',source:'Current customisation feedback · pending owner confirmation'},family:{match:/family|five|children|kids/i,text:'The villa can be tailored for your family’s preferred bedroom count, shared spaces and outdoor needs within the approximate 1,500–4,500 sq ft range. Final planning would follow a design consultation.',tag:'FAMILY-LED PLANNING',title:'A home shaped for your family',detail:'Flexible rooms · personalised layout · 1,500–4,500 sq ft',image:'assets/project-02.jpg',source:'Current customisation feedback · pending owner confirmation'},amenities:{match:/amenit|pool|club|fitness|security/i,text:'The concept includes a clubhouse, swimming pool, fitness studio, children’s grove, walking loop and round-the-clock gated security.',tag:'SHARED LIFESTYLE',title:'More than a home',detail:'12+ illustrative shared amenities designed around wellbeing and connection.',image:'assets/about-photo.jpg',source:'Concept amenities schedule'},location:{match:/location|near|thrissur|town|hospital|mall|shopping|essential|city|map/i,text:'Thrissur Town is approximately 7 km away. Multi-speciality hospitals are within about 10–15 km, while malls and essential shopping venues are within approximately 10 km. These distances remain pending owner verification.',tag:'LOCATION PREVIEW',title:'Connected to Thrissur',detail:'Thrissur Town · 7 km | Hospitals · 10–15 km | Malls & essentials · within 10 km',image:'assets/location-map.jpg',source:'Current feedback · pending owner verification'},visit:{match:/visit|schedule|contact|call|book/i,text:'I can demonstrate a visit-request journey, but this prototype does not send your details. In the live application, an approved sales contact would receive the request.',tag:'DEMO ENQUIRY FLOW',title:'Plan a private visit',detail:'No information is collected or submitted in this concept demonstration.',image:'assets/hero-01.jpg',source:'Prototype interaction only',toast:true},grove:{match:/grove/i,text:'The Grove is an illustrative courtyard-led design direction. Its size and room arrangement can be tailored to individual requirements within the approximate 1,500–4,500 sq ft range.',tag:'VILLA 01 · DESIGN DIRECTION',title:'The Grove',detail:'Courtyard living · tailored plan · 1,500–4,500 sq ft',image:'assets/project-01-villa-only.png',source:'Illustrative design direction'},courtyard:{match:/courtyard|compare/i,text:'The Courtyard is an illustrative garden-focused design direction. The final plan, room mix and built-up area can be tailored to the owner’s requirements.',tag:'VILLA 02 · DESIGN DIRECTION',title:'The Courtyard',detail:'Garden connection · tailored plan · 1,500–4,500 sq ft',image:'assets/project-02.jpg',source:'Illustrative design direction'},canopy:{match:/canopy/i,text:'The Canopy is an illustrative signature design direction that can be personalised for the owner’s space and lifestyle needs, up to approximately 4,500 sq ft.',tag:'VILLA 03 · DESIGN DIRECTION',title:'The Canopy',detail:'Signature space · tailored plan · up to 4,500 sq ft',image:'assets/project-03.jpg',source:'Illustrative design direction'},default:{text:'This concept assistant currently knows about villa customisation, family needs, amenities, location and visit requests. Try asking one of those questions.',tag:'DEMO ASSISTANT',title:'Let’s explore together',detail:'Choose a topic to see a matching visual summary and reference.',image:'assets/hero-02.jpg',source:'Concept presentation'}};
function openChat(question){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');backdrop.hidden=false;document.body.classList.add('chat-is-open');document.body.style.overflow='hidden';launcher.setAttribute('aria-expanded','true');setTimeout(()=>input.focus(),350);if(question)setTimeout(()=>respond(question),200)}function closeChat(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');backdrop.hidden=true;document.body.classList.remove('chat-is-open');document.body.style.overflow='';launcher.setAttribute('aria-expanded','false');launcher.focus()}function selectAnswer(q){return Object.values(answers).find(a=>a.match&&a.match.test(q))||answers.default}function respond(q){if(!q.trim())return;messages.insertAdjacentHTML('beforeend',`<div class="message user"><p>${escapeHtml(q)}</p></div>`);const a=selectAnswer(q);setTimeout(()=>{messages.insertAdjacentHTML('beforeend',`<div class="message assistant"><span>GP</span><p>${a.text}</p></div>`);messages.scrollTop=messages.scrollHeight;preview.innerHTML=`<div class="preview-image" style="background-image:url('${a.image}')"><span>LIVE PREVIEW</span></div><div class="preview-content"><small>${a.tag}</small><h3>${a.title}</h3><p>${a.detail}</p><div class="preview-source">Reference · ${a.source}</div></div>`;if(a.toast){toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2800)}},420)}function escapeHtml(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}document.querySelectorAll('[data-open-chat]').forEach(b=>b.addEventListener('click',()=>openChat()));document.querySelectorAll('#suggestions button').forEach(b=>b.addEventListener('click',()=>respond(b.textContent)));document.querySelector('#closeChat').addEventListener('click',closeChat);backdrop.addEventListener('click',closeChat);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))closeChat()});document.querySelector('#chatForm').addEventListener('submit',e=>{e.preventDefault();const q=input.value;input.value='';respond(q)});
